SELECT 
FROM rare_book
WHERE deleted = 0

    AND book_code LIKE CONCAT('%', #{bookCode}, '%')


    AND book_name LIKE CONCAT('%', #{bookName}, '%')


    AND author LIKE CONCAT('%', #{author}, '%')


    AND dynasty = #{dynasty}


    AND condition_level = #{conditionLevel}


    AND status = #{status}

ORDER BY create_time DESC
LIMIT #{pageSize} OFFSET #{(pageNum - 1) * pageSize}

SELECT COUNT(*)
FROM rare_book
WHERE deleted = 0

    AND book_code LIKE CONCAT('%', #{bookCode}, '%')


    AND book_name LIKE CONCAT('%', #{bookName}, '%')


    AND author LIKE CONCAT('%', #{author}, '%')


    AND dynasty = #{dynasty}


    AND condition_level = #{conditionLevel}


    AND status = #{status}
